import pytest

from bedrock_protocol import v1001, v2168, v2225

versions = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735 and again at bd45132:
# packet.ServerBoundDataDrivenScreenClosed{FormID: 7, CloseReason: "userbusy"}
USER_BUSY = bytes.fromhex("07000000087573657262757379")

# generated by gophertunnel b8bd735 and again at bd45132:
# packet.ServerBoundDataDrivenScreenClosed{FormID: 300, CloseReason: "programmaticcloseall"}
CLOSE_ALL = bytes.fromhex("2c0100001470726f6772616d6d61746963636c6f7365616c6c")

# generated by gophertunnel b8bd735 and again at bd45132:
# packet.ServerBoundDataDrivenScreenClosed{CloseReason: "programmaticclose"}
PROGRAMMATIC_CLOSE = bytes.fromhex("000000001170726f6772616d6d61746963636c6f7365")

# generated by gophertunnel b8bd735 and again at bd45132:
# packet.ServerBoundDataDrivenScreenClosed{CloseReason: "clientcanceled"}
CLIENT_CANCELED = bytes.fromhex("000000000e636c69656e7463616e63656c6564")

# generated by gophertunnel b8bd735 and again at bd45132:
# packet.ServerBoundDataDrivenScreenClosed{CloseReason: "invalidform"}
INVALID_FORM = bytes.fromhex("000000000b696e76616c6964666f726d")

GOLDENS = (
    [
        pytest.param(
            v.ServerboundDataDrivenScreenClosedPacket(form_id=7, close_reason=v.DataDrivenScreenClosedReason.USER_BUSY),
            USER_BUSY,
            id=f"{v.__name__.rpartition('.')[2]}-user-busy",
        )
        for v in versions
    ]
    + [
        pytest.param(
            v.ServerboundDataDrivenScreenClosedPacket(
                form_id=300, close_reason=v.DataDrivenScreenClosedReason.PROGRAMMATIC_CLOSE_ALL
            ),
            CLOSE_ALL,
            id=f"{v.__name__.rpartition('.')[2]}-four-byte-form-id",
        )
        for v in versions
    ]
    + [
        pytest.param(
            v.ServerboundDataDrivenScreenClosedPacket(close_reason=v.DataDrivenScreenClosedReason.PROGRAMMATIC_CLOSE),
            PROGRAMMATIC_CLOSE,
            id=f"{v.__name__.rpartition('.')[2]}-programmatic-close",
        )
        for v in versions
    ]
    + [
        pytest.param(
            v.ServerboundDataDrivenScreenClosedPacket(close_reason=v.DataDrivenScreenClosedReason.CLIENT_CANCELED),
            CLIENT_CANCELED,
            id=f"{v.__name__.rpartition('.')[2]}-client-canceled",
        )
        for v in versions
    ]
    + [
        pytest.param(
            v.ServerboundDataDrivenScreenClosedPacket(close_reason=v.DataDrivenScreenClosedReason.INVALID_FORM),
            INVALID_FORM,
            id=f"{v.__name__.rpartition('.')[2]}-invalid-form",
        )
        for v in versions
    ]
)


@pytest.mark.parametrize("version", versions)
def test_serverbound_data_driven_screen_closed_is_packet_343(version):
    assert version.packets[343] is version.ServerboundDataDrivenScreenClosedPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_serverbound_data_driven_screen_closed_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_serverbound_data_driven_screen_closed_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
